 "content": "def transform(grid):
    """Expand the inner color two cells outward from the rectangular object."""
    h, w = len(grid), len(grid[0])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not pts:
        return [row[:] for row in grid]
    r0 = min(r for r, c in pts)
    r1 = max(r for r, c in pts)
    c0 = min(c for r, c in pts)
    c1 = max(c for r, c in pts)
    colors = {}
    for r, c in pts:
        colors[grid[r][c]] = colors.get(grid[r][c], 0) + 1
    # The fill is the non-background color occupying the interior of the object.
    inner = max(colors, key=colors.get)
    out = [row[:] for row in grid]
    for r in range(max(0, r0 - 2), min(h, r1 + 3)):
        for c in range(max(0, c0 - 2), min(w, c1 + 3)):
            if out[r][c] == 0:
                out[r][c] = inner
    return out
