    h, w = len(grid), len(grid[0])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not pts:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    counts = {}
    for r, c in pts:
        counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    fill = min(counts, key=counts.get)
    special = [(r, c) for r, c in pts if grid[r][c] == fill]
    sr0, sr1 = min(r for r, c in special), max(r for r, c in special)
    sc0, sc1 = min(c for r, c in special), max(c for r, c in special)
    ih, iw = sr1 - sr0 + 1, sc1 - sc0 + 1
    # A filled rectangle with a marker gets a one-cell halo. For a framed
    # rectangle, the enclosed special patch sets the halo scale: square patches
    # expand by their side, while a nonsquare patch uses its short side minus one.
    has_hole = any(grid[r][c] == 0 for r in range(r0, r1 + 1) for c in range(c0, c1 + 1))
    if has_hole:
        pad = min(ih, iw) if ih == iw else max(1, min(ih, iw) - 1)
    else:
        pad = 1
    out = [row[:] for row in grid]
    for r in range(max(0, r0 - pad), min(h, r1 + pad + 1)):
        for c in range(max(0, c0 - pad), min(w, c1 + pad + 1)):
            if out[r][c] == 0:
                out[r][c] = fill
    return out
